import os
from azure.core.credentials import AzureKeyCredential
from azure.ai.formrecognizer import DocumentAnalysisClient

def analyze_document_layout(document_url: str):
    """
    Extracts table cells and row structure from a document using Azure Form Recognizer.

    Args:
        document_url: The URL to the document to analyze.

    Returns:
        A list of dictionaries, where each dictionary represents a table
        and contains its cells, rows, and column information.
    """
    # Set up Azure Form Recognizer client
    endpoint = os.environ["AZURE_FORM_RECOGNIZER_ENDPOINT"]
    key = os.environ["AZURE_FORM_RECOGNIZER_KEY"]

    document_analysis_client = DocumentAnalysisClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    poller = document_analysis_client.begin_analyze_document_from_url(
        "prebuilt-layout", document_url
    )
    result = poller.result()

    tables_data = []
    if result.tables:
        for table_idx, table in enumerate(result.tables):
            table_info = {
                "bounding_regions": [
                    {
                        "page_number": region.page_number,
                        "bounding_box": [
                            (point.x, point.y) for point in region.bounding_box
                        ],
                    }
                    for region in table.bounding_regions
                ],
                "row_count": table.row_count,
                "column_count": table.column_count,
                "cells": [],
            }
            for cell in table.cells:
                cell_info = {
                    "content": cell.content,
                    "row_index": cell.row_index,
                    "column_index": cell.column_index,
                    "row_span": cell.row_span if cell.row_span > 1 else 1,
                    "column_span": cell.column_span if cell.column_span > 1 else 1,
                    "bounding_regions": [
                        {
                            "page_number": region.page_number,
                            "bounding_box": [
                                (point.x, point.y) for point in region.bounding_box
                            ],
                        }
                        for region in cell.bounding_regions
                    ],
                }
                table_info["cells"].append(cell_info)
            tables_data.append(table_info)

    return tables_data
